  "contact_profile": {
    "headline": "Director–SBA Lending at First Citizens Bank, specializing in SBA 7(a), 504, USDA and wholesale SBA financing for small and mid-sized businesses.",
    "role_summary": "Oversees SBA lending and wholesale SBA programs at First Citizens Bank, helping business owners use government-backed financing to acquire real estate, equipment, and long-term assets while preserving working capital.[1][3][5]",
    "seniority": "Director",
    "background_bullets": [
      {
        "text": "Serves as Director-SBA Lending (including SBA Wholesale Lending) at First Citizens Bank, based in Carlsbad, California, focusing on SBA and USDA-backed credit solutions for business clients.[1][2][3][5]"
      },
      {
        "text": "Frequently quoted by First Citizens in small-business finance content on topics like SBA 7(a), 504 and USDA loans, commercial real estate purchases, and manufacturer equipment investment strategy.[3][5]"
      },
      {
        "text": "Previously held roles at CIT, bringing a background in specialized and government-backed lending into the current SBA leadership role at First Citizens.[1]"
      }
    ]
  },
  "company_profile": {
    "one_liner": "First Citizens Bank is a large U.S. commercial bank offering a full suite of retail, business, and SBA lending solutions nationwide.",
    "industry": "Banking and Financial Services",
    "size_segment": "Enterprise",
    "region": "United States (national footprint, including California presence)",
    "key_products_or_services": [
      {
        "text": "SBA lending programs including SBA 7(a), 504 and USDA business loans for commercial real estate, equipment and working capital.[3][5]"
      },
      {
        "text": "Small-business and commercial banking services, including government-backed loans tailored to manufacturers and other growth-focused businesses.[3][5]"
      },
      {
        "text": "Advisory-centric lending approach emphasizing long-term relationships and helping clients scale facilities, expand locations and invest in durable assets.[3][5]"
      }
    ]
  },
  "messaging": {
    "cold_openers": [
      {
        "text": "You’ve been a visible voice for SBA-backed real estate and equipment financing at First Citizens—especially around using 504 and 7(a) to balance growth and liquidity—and I had an idea on how to make that process even easier for your borrowers.[3][5]"
      },
      {
        "text": "In your comments on SBA 504 and USDA real estate loans, you highlight helping owners build long-term wealth through their facilities; I’d love to share a way to streamline that journey from first property to multi-location expansion.[3]"
      }
    ],
    "value_props": [
      {
        "text": "Support your SBA and wholesale lending strategy by giving borrowers clearer, faster paths from application to closing, so your team can focus on higher-value advisory conversations rather than manual process friction."
      },
      {
        "text": "Help manufacturers and real-estate buyers model different SBA 7(a)/504 structures in minutes, reinforcing your message about preserving working capital while investing in long-term assets.[3][5]"
      },
      {
        "text": "Provide portfolio-level visibility into SBA pipeline and partner activity, aligning with your focus on scalable, community-based growth and long-term client relationships.[3][5]"
      }
    ],
    "call_to_action_ideas": [
      {
        "text": "Propose a 20–25 minute call to walk through how peers in SBA and wholesale lending are shortening time-to-close while keeping strict credit standards."
      },
      {
        "text": "Offer to review one or two recent SBA 504/7(a) scenarios your team handled and show how the workflow could look with a more automated, borrower-friendly experience."
      },
      {
        "text": "Suggest a brief working session with you and a member of your SBA operations or credit team to map where technology could free up more capacity for relationship-focused work."
      }
